import sys
from multiprocessing import Pool, cpu_count


def make_tree(d):
    if d == 0:
        return (None, None)
    d -= 1
    return (make_tree(d), make_tree(d))


def check_tree(node):
    left, right = node
    if left is None:
        return 1
    return 1 + check_tree(left) + check_tree(right)


def run_chunk(args):
    depth, count = args
    total = 0
    mk = make_tree
    ck = check_tree
    for _ in range(count):
        total += ck(mk(depth))
    return total


def main():
    n = int(sys.argv[1])
    min_depth = 4
    max_depth = max(min_depth + 2, n)
    stretch_depth = max_depth + 1

    out = []
    out.append("stretch tree of depth %d\t check: %d"
               % (stretch_depth, check_tree(make_tree(stretch_depth))))

    long_lived_tree = make_tree(max_depth)

    depths = list(range(min_depth, max_depth + 1, 2))
    try:
        workers = cpu_count()
    except Exception:
        workers = 1
    workers = max(1, workers)

    # Build task list: split each depth's iterations into chunks
    tasks = []
    task_depths = []
    for d in depths:
        iterations = 2 ** (max_depth - d + min_depth)
        nchunks = min(iterations, workers * 4)
        base, rem = divmod(iterations, nchunks)
        for i in range(nchunks):
            cnt = base + (1 if i < rem else 0)
            if cnt > 0:
                tasks.append((d, cnt))
                task_depths.append(d)

    if workers > 1 and len(tasks) > 1:
        with Pool(workers) as pool:
            results = pool.map(run_chunk, tasks, chunksize=1)
    else:
        results = [run_chunk(t) for t in tasks]

    sums = {d: 0 for d in depths}
    for d, r in zip(task_depths, results):
        sums[d] += r

    for d in depths:
        iterations = 2 ** (max_depth - d + min_depth)
        out.append("%d\t trees of depth %d\t check: %d" % (iterations, d, sums[d]))

    out.append("long lived tree of depth %d\t check: %d"
               % (max_depth, check_tree(long_lived_tree)))

    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
```

