import sys
from math import sqrt


def eval_A(i, j):
    ij = i + j
    return 1.0 / (ij * (ij + 1) // 2 + i + 1)


def run_numpy(n):
    import numpy as np
    i = np.arange(n, dtype=np.float64)[:, None]
    j = np.arange(n, dtype=np.float64)[None, :]
    s = i + j
    A = 1.0 / (s * (s + 1.0) * 0.5 + i + 1.0)
    AT = A.T  # view, no copy
    u = np.ones(n, dtype=np.float64)
    v = np.empty(n, dtype=np.float64)
    for _ in range(10):
        v = AT @ (A @ u)
        u = AT @ (A @ v)
    vBv = float(u @ v)
    vv = float(v @ v)
    return sqrt(vBv / vv)


def part_A_times_u(u, rng):
    n = len(u)
    out = []
    for i in rng:
        s = 0.0
        for j in range(n):
            s += eval_A(i, j) * u[j]
        out.append(s)
    return out


def part_At_times_u(u, rng):
    n = len(u)
    out = []
    for i in rng:
        s = 0.0
        for j in range(n):
            s += eval_A(j, i) * u[j]
        out.append(s)
    return out


def run_pure(n):
    u = [1.0] * n
    for _ in range(10):
        v = part_At_times_u(part_A_times_u(u, range(n)), range(n))
        u = part_At_times_u(part_A_times_u(v, range(n)), range(n))
    vBv = sum(a * b for a, b in zip(u, v))
    vv = sum(b * b for b in v)
    return sqrt(vBv / vv)


def main():
    n = int(sys.argv[1])
    try:
        import numpy  # noqa: F401
        result = run_numpy(n)
    except ImportError:
        result = run_pure(n)
    print("%0.9f" % result)


if __name__ == "__main__":
    main()
