import sys
from array import array
from collections import Counter


def read_three():
    data = sys.stdin.buffer.read()
    i = data.find(b'>THREE')
    if i < 0:
        return b''
    j = data.find(b'\n', i)
    if j < 0:
        return b''
    end = data.find(b'>', j)
    if end < 0:
        end = len(data)
    seq = data[j + 1:end]
    seq = seq.replace(b'\n', b'').replace(b'\r', b'')
    return seq.upper()


def freq_lines(counts, n, out):
    items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    for k, c in items:
        out.append("%s %.3f" % (k, 100.0 * c / n if n > 0 else 0.0))
    out.append("")


def main():
    _ = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    seq = read_three()
    L = len(seq)
    out = []

    # 1-mers
    c1 = Counter(seq)
    counts1 = {chr(b): c for b, c in c1.items()}
    freq_lines(counts1, L, out)

    # 2-mers (overlapping) via uint16 views at even and odd offsets
    counts2 = {}
    if L >= 2:
        even_len = L - (L % 2)
        evens = array('H', seq[:even_len])
        odd_len = ((L - 1) // 2) * 2
        odds = array('H', seq[1:1 + odd_len])
        c2 = Counter(evens)
        c2.update(odds)
        for v, c in c2.items():
            key = array('H', [v]).tobytes().decode('ascii')
            counts2[key] = c
    freq_lines(counts2, L - 1, out)

    # specific fragments (none self-overlap, so bytes.count is exact)
    for frag in ("GGT", "GGTA", "GGTATT", "GGTATTTTAATT", "GGTATTTTAATTTATAGT"):
        out.append("%d\t%s" % (seq.count(frag.encode('ascii')), frag))

    sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
